const takeOver = () => { touring = false; clearTimeout(idleTimer); idleTimer = setTimeout(() => { if (!still.matches) { touring = true; idleClock = 0; run(); } }, 6000); };
const userTest = () => { takeOver(); startTest(); };
new IntersectionObserver((entries) => { visible = entries[entries.length - 1].isIntersecting; if (visible) run(); }, { rootMargin: "120px 0px" }).observe(stageEl);
stageEl.addEventListener("click", userTest);
testButton.addEventListener("click", (e) => { e.stopPropagation(); userTest(); });
